// PostWxaSecVodGetmedialink 获取媒资播放链接 (POST /wxa/sec/vod/getmedialink)
// Doc: https://developers.weixin.qq.com/miniprogram/dev/server/API/minidrama/vod_media/api_getmedialink.html
// PostWxaSecVodGetmedialinkRequest carries the documented parameters of one API call.
type PostWxaSecVodGetmedialinkRequest struct {
	// 媒资文件id
	MediaID int64 `json:"media_id"`
	// 播放地址的过期时间戳。有效的时间最长不能超过2小时后
	T int64 `json:"t"`
	// 链接标识。平台默认会生成一个仅包含小写字母和数字的字符串用于增强链接的唯一性(如us=647488c4792c15185b8fd2a6)。如开发者需要增加自己的标识,比如区分播放的渠道,可使用该参数,该参数最终的值是"开发者标识-平台标识"(如开发者传入abcd,则最终的临时链接中us=abcd-647488c4792c15185b8fd2a6)
	Us string `json:"us,omitempty"`
	// 试看时长,单位:秒,最大值不能超过视频长度
	Exper int64 `json:"exper,omitzero"`
	// 最多允许多少个不同 IP 的终端播放,以十进制表示,最大值为9,不填表示不做限制。当限制 URL 只能被1个人播放时,建议 rlimit 不要严格限制成1(例如可设置为3),因为移动端断网后重连 IP 可能改变
	Rlimit int64 `json:"rlimit,omitzero"`
	// 允许访问的域名列表,支持1条 - 10条,用半角逗号分隔。域名前不要带协议名(http://和https://),域名为前缀匹配(如填写 abc.com,则 abc.com/123 和 abc.com.cn也会匹配),且支持通配符(如 *.abc.com)
	Whref string `json:"whref,omitempty"`
	// 禁止访问的域名列表,支持1条 - 10条,用半角逗号分隔。域名前不要带协议名(http://和https://),域名为前缀匹配(如填写 abc.com,则 abc.com/123 和 abc.com.cn也会匹配),且支持通配符(如 *.abc.com)
	Bkref string `json:"bkref,omitempty"`
}

